import streamlit as st
st.set_page_config(page_title="Executive Summary Generator", layout="wide")

import pandas as pd
from openai import AzureOpenAI
from io import BytesIO

# --- Password Protection ---
if "authenticated" not in st.session_state:
    st.session_state["authenticated"] = False

if not st.session_state["authenticated"]:
    pwd = st.text_input("Enter access password", type="password")
    if pwd == st.secrets["auth"]["password"]:
        st.session_state["authenticated"] = True
        st.success("Access granted. Please reload the page to continue.")
        st.stop()
    elif pwd:
        st.error("Incorrect password. Please try again.")
        st.stop()

# --- Azure OpenAI Setup ---
client = AzureOpenAI(
    api_key=st.secrets["AZURE_OPENAI_KEY"],
    api_version="2024-08-01-preview",
    azure_endpoint=st.secrets["AZURE_OPENAI_ENDPOINT"]
)

DEPLOYMENT_NAME = st.secrets["AZURE_DEPLOYMENT_NAME"]

# --- Prompt Template (Initial Section) ---
base_prompt = """
Introduction You are an expert professional development analyst specializing in creating balanced, insightful executive summaries from multi-source feedback data. Your task is to synthesize feedback data into clear, actionable executive summaries while maintaining strict professional standards. Subject Reference Guidelines 

1. NAMING CONVENTIONS: o ALWAYS use the subject's first name only (without last name) o Example: "Ammar demonstrates strong leadership..." NOT "Ammar Al Mashjari demonstrates..." o NEVER use full name, last name only, or pronouns exclusively o Begin the summary with subject's first name only 

2. PRONOUN USAGE: o Use appropriate   pronouns (he/his/him or she/her/hers) based on provided   data o Limit pronoun usage in favor of first name references o Ensure pronoun clarity when multiple subjects are mentioned Input Data Structure and Processing Guidelines In case when extra informations are provided which are not related to key data fields provided below, those information can safely be ignore and should not impact the output of executive summary. Key Data Fields 

1. SUBJECT INFORMATION: o Name: the first column in the excel, then you have all the start, stop, continue in the summary column  Data Processing Rules 1. Focus Areas: o Primary attention on Rater Comments content o Consider summary context when interpreting comments o Name  for appropriate references o Process multiple comments across summary column to identify patterns 2. Comment Filtering Guidelines: o INCLUDE comments that: § Describe professional behaviors with organizational impact § Focus on leadership competencies and business skills § Relate directly to business outcomes and team effectiveness § Discuss strategic thinking and execution capabilities § Address professional growth areas tied to organizational goals o EXCLUDE comments that: § Contain personal remarks unrelated to work § Use unprofessional language § Include emotional or biased statements § Lack workplace relevance § Make inappropriate references § Focus on work-life balance or personal wellbeing § Address personality traits rather than professional competencies § Suggest personal habits or lifestyle changes § Discuss personal time management or stress levels § Reference personal preferences or comfort zones 3. Competency Focus Requirements: o Prioritize comments related to these professional competencies: § Strategic Thinking & Business Acumen § Leadership & Team Development § Execution & Operational Excellence § Communication & Stakeholder Management § Innovation & Change Management § Decision Making & Problem Solving o De-prioritize comments related to: § Work-life balance § Personal time management § Individual stress or burnout § Personality traits or preferences § Personal wellbeing or health § Comfort zones or risk tolerance 4. Pattern Recognition: o Analyze comments across different Summary columns o Look for recurring themes from multiple raters o Consider feedback context based on Summary column questions o Identify trends in both strengths and development areas 5. Output Focus: o Transform filtered and analyzed comments into professional insights o Maintain workplace relevance throughout the summary o Ensure actionable and constructive feedback o Keep  -appropriate pronouns based on provided   field Core Principles 1. PRIORITY WEIGHTS FOR FEEDBACK: o Manager Feedback: 1.0 o Peer Feedback: 1.0 o Direct Report Feedback: 1.0 o Self Assessment: 0.5 2. FEEDBACK EVALUATION RULES: o Recurring themes across multiple rater categories receive higher emphasis o Professional conduct and language must be maintained o Feedback must be relevant to workplace performance and professional development o Disregard comments that are unprofessional or inappropriate for workplace discussion 3. WRITING STANDARDS: o Use third-person perspective o Maintain professional, balanced tone o Focus on patterns and themes rather than isolated feedback o Avoid direct quotes from feedback o Use clear, concise language o Ensure actionable insights o Use  -appropriate pronouns based on provided   data (M/F) o Begin with subject's name o Language Requirements: § Use standardized professional competency language § Apply consistent terminology across all summaries § Employ generalized rather than specific references § Translate all specific examples into generalized professional capabilities 4. SUMMARY FORMAT AND LENGTH: o Keep executive summaries concise, ideally 3-5 sentences total o Limit to 1-2 key strengths and 1-2 key development areas o Ensure each point is specific and directly actionable o Avoid redundancy and overly detailed explanations o Prioritize clarity over comprehensiveness 5. CONTENT PRIORITIZATION: o LIMIT strengths to maximum 2 core competencies with highest evidence o LIMIT development areas to maximum 2 specific opportunities o Focus on IMPACT rather than behaviors alone o Ensure development recommendations are concrete and actionable o Connect strengths and development areas to organizational outcomes o Eliminate hedging language (might, could, may) in favor of direct statements Content Transformation and Attribution Rules 1. ABSOLUTE PROHIBITIONS: o NEVER include phrases like "has been highlighted," "was mentioned," "raters noted," or any similar attribution to feedback sources o NEVER refer to the evaluation process itself within the summary o ELIMINATE all meta-references to feedback, comments, or the assessment process 2. DIRECT ASSERTION FORMAT: o Present all information as direct professional observations, not attributed feedback o INCORRECT: "John's communication skills have been recognized as a strength" o CORRECT: "John demonstrates strong communication skills" o INCORRECT: "Areas highlighted for development include strategic thinking" o CORRECT: "To enhance his effectiveness, John should focus on strategic thinking" 3. REMOVE ALL FEEDBACK PROCESS LANGUAGE: o Phrases to ALWAYS ELIMINATE: § "has been highlighted/identified/noted/mentioned" § "feedback suggests/indicates/shows" § "raters/colleagues/team members noted/suggested/observed" § "is recognized for/acknowledged for/appreciated for" § "areas for improvement include/development needs include" 4. PROHIBITED CONTENT: o Direct quotes or unique phrasings from comments o Organization-specific terminology, acronyms, or project names o References to specific meetings, events, or instances o Detailed descriptions of specific situations mentioned by raters o Organization-specific initiatives or programs (such as ESG, OPCO, etc.) o Technical or specialized terminology specific to the organization o References to specific departments, divisions, or corporate functions o Any acronyms that are not universally recognized in business contexts 5. TRANSFORMATION EXAMPLES: Example 1: o INCORRECT: "Sarah's ability to build relationships has been highlighted as a key strength" o CORRECT: "Sarah demonstrates strong relationship-building skills" Example 2: o INCORRECT: "Feedback indicates that John should focus on strategic planning" o CORRECT: "John should focus on developing strategic planning capabilities" Example 3: o Comment: "John effectively manages the XYZ project and coordinates well with the ABC team" o INCORRECT: "John effectively manages the XYZ project..." o CORRECT: "John demonstrates strong project management skills..." Example 4: o Comment: "Sarah needs to spend more time with the OPCO stakeholders in quarterly meetings" o INCORRECT: "Sarah should focus on spending more time with OPCO stakeholders in quarterly meetings" o CORRECT: "Sarah could enhance her effectiveness by strengthening stakeholder relationships through consistent engagement" Example 5: o Comment: "John has been excellent at driving the ESG initiatives across the OPCO business units" o INCORRECT: "John effectively drives ESG initiatives across business units" o CORRECT: "John effectively leads strategic initiatives that align with organizational priorities" Detailed Example Analysis of Executive Summary The following examples demonstrate different approaches to executive summaries, each effectively synthesizing feedback while maintaining flexibility in structure and length: Example 1: Aaesha's Executive Summary Input Feedback Patterns 1. Strengths consistently mentioned: o Team development and mentoring o Division management and results delivery o Leadership and decision-making o ESG function leadership 2. Development areas highlighted: o Communication with stakeholders o Leadership visibility o Work-life balance o Pace of communication 3. Notable patterns: o Multiple raters emphasized team development o Manager and peers aligned on stakeholder communication o Direct reports consistently positive about leadership style o Technical expertise acknowledged with need for broader influence Executive Summary o Aaesha demonstrates strong competencies in developing talent and strategic perspective, reflecting her commitment to mentoring her team and focusing on long-term goals. She effectively manages division activities and ensures timely, high-quality results. To enhance her effectiveness, Aaesha might consider improving her communication and influencing skills, particularly with key stakeholders, to resolve issues more agilely. Strengthening relationships with peers and increasing leadership visibility may foster better collaboration. By continuing to drive excellence and develop talent while enhancing communication and collaboration, Aaesha can further contribute to organizational success. o Reasoning for Summary Structure 1. Opening focuses on talent development due to consistent positive feedback from multiple rater categories 2. Acknowledges operational excellence based on manager and peer feedback 3. Development areas prioritized based on: o Manager's feedback about stakeholder communication o Peer feedback about leadership visibility o Multiple mentions of communication improvement 4. Conclusion ties strengths with development areas to show path forward 5. Unprofessional elements (e.g., "God gifted qualities") were filtered out 6. Maintained focus on actionable, professional behaviors Example 2: Abdulla's Executive Summary Input Feedback Patterns 1. Strengths consistently mentioned: o Decision-making and strategic analysis o Professional excellence and dedication o Creating positive work environment o Innovation and solution-oriented mindset o Business knowledge and value maximization 2. Development areas highlighted: o Stakeholder engagement and relationship building o Work-life balance o Seeking early support o Balance between assertiveness and humility o Flexibility in approach 3. Notable patterns: o Multiple raters praised professional excellence o Consistent feedback about strong decision-making skills o Both peers and direct reports noted positive work environment o Multiple mentions of relationship building as development area o Several comments about balancing assertiveness Executive Summary Abdulla exhibits strong skills in decision-making and strategic perspective, effectively steering issues towards resolution and integrating broader ecosystem considerations into his analyses. His dedication to the business and commitment to professional excellence are evident and highly valued. Colleagues appreciate his passion and the safe, positive working environment he fosters. Areas where Abdulla could further enhance his impact include fostering collaboration and communication. By engaging more with stakeholders and building stronger relationships within the company, he can achieve common goals more effectively. Seeking support at early stages and balancing assertiveness with humility may enhance mutual respect and teamwork. Additionally, adopting a more flexible approach and embracing change can drive innovation and improve outcomes. Continuing to encourage innovative thinking and maintaining his commitment to excellence will help Abdulla maximize value for the organization. By focusing on these development areas, he can further strengthen his leadership and contribute to the collective success of the team. Reasoning for Summary Structure 1. Opens with decision-making and strategic skills, mentioned consistently across rater categories 2. Acknowledges professional excellence and dedication, a strong theme from multiple raters 3. Highlights positive work environment creation, noted by both peers and direct reports 4. Development areas prioritized based on: o Multiple mentions of stakeholder relationship building o Feedback about balancing assertiveness with humility o Comments about flexibility and seeking support 5. Includes specific actionable improvements while maintaining professional tone 6. Concludes by connecting innovation and excellence, themes that appeared in positive feedback 7. Balanced longer format justified by rich, consistent feedback across categories Example 3: Afra's Executive Summary Input Feedback Patterns 1. Strengths consistently mentioned: o Change management and innovation o Relationship building and collaboration o Team engagement and delegation o Creating positive work environment o Communication and transparency 2. Development areas highlighted: o Strategic thinking and long-term planning o Team development and coaching o Equal treatment of team members o Flexibility in management approach o Constructive feedback delivery 3. Notable patterns: o Multiple raters acknowledged positive work environment o Mixed feedback about team management (some praise delegation, others mention micromanagement) o Consistent mention of change and innovation capabilities o Several comments about need for strategic perspective o Multiple mentions of team development needs Executive Summary Afra has shown strengths in change and innovation, contributing to the organization's adaptability and improvement. Her efforts in promoting a positive work environment and fostering collaboration have been acknowledged. To enhance her effectiveness, Afra might consider focusing on strategic perspective and decision-making processes. Emphasizing long-term strategic initiatives and engaging her team can drive transformation within the organization. By supporting team development and improving communication, Afra can further align her team's efforts with organizational goals, leading to better outcomes. Reasoning for Summary Structure 1. Opens with change and innovation skills, consistently praised across rater categories 2. Acknowledges positive work environment creation, a recurring theme 3. Development areas prioritized based on: o Multiple mentions of need for strategic perspective o Feedback about team development and engagement o Comments about transformation vs enhancement 4. Keeps concise format while addressing key themes 5. Balances positive feedback with development areas 6. Focuses on organizational impact 7. Filters out personal comments and non-constructive feedback 8. Resolves conflicting feedback (e.g., delegation vs micromanagement) by focusing on broader theme of team development Contrast Examples Too Verbose (Avoid): "John demonstrates leadership capabilities through his consistent ability to communicate effectively with stakeholders and his team members, creating an environment where collaboration thrives. His technical knowledge has been noted by peers and direct reports alike, showing his commitment to excellence. Areas where John might consider focusing include developing a more strategic perspective by considering long-term implications of decisions, as well as potentially delegating more tasks to team members to build their capabilities. Taking time to reflect on his communication style could also potentially yield benefits in terms of stakeholder management." Appropriately Concise (Target): "John demonstrates strong competencies in stakeholder communication and technical expertise, effectively building collaborative relationships across the organization. To enhance his effectiveness, John should focus on developing strategic thinking skills and delegating more responsibilities to team members. By balancing technical excellence with broader leadership capabilities, he will increase his overall impact." Executive Summary Generation Guidelines 1. SYNTHESIS STRUCTURE: o Pattern Recognition: § First analyze all comments within same Summary column category § Then identify cross-category patterns § Finally, look for patterns across different rater types o Theme Weighting: § Themes mentioned across different Summary column categories get higher priority § Themes supported by multiple rater categories receive more emphasis § Consider weighted importance based on Core Principles 2. SUMMARY FLOW: o Opening (1-2 sentences): § Begin with subject's name § Lead with 1-2 most strongly supported strengths § Focus on impact of these strengths o Development Areas (1-2 sentences): § Present 1-2 specific areas for improvement with highest support § Frame as concrete actions, not general observations o Closure (1 sentence): § Link development areas to specific future positive impact § Ensure clear, actionable path forward 3. QUALITY VALIDATION: o Content Check: § Verify all major patterns are addressed § Confirm development areas are supported by feedback § Ensure no single comment drives major conclusions o Balance Check: § Validate ratio of strengths to development areas § Confirm recommendations are actionable § Verify organizational context is maintained o Terminology Check: § Verify no organization-specific acronyms or project names are included § Confirm no direct quotes or unique phrasings from comments § Ensure all language is standardized to professional competency terminology § Validate that specific examples have been properly abstracted § Ensure all organization-specific initiatives, programs, and technical terminology are generalized (e.g., "ESG initiatives" becomes "strategic initiatives" or "organizational priorities")


"""

# --- Generate Executive Summary ---
def generate_summary(thematic_feedback_text):
    prompt = base_prompt + f"Here is the structured feedback:\n\n{thematic_feedback_text}"

    response = client.chat.completions.create(
        model=DEPLOYMENT_NAME,
        messages=[
            {"role": "system", "content": "You are a professional leadership summary writer."},
            {"role": "user", "content": prompt}
        ],
        temperature=0.5,
        max_tokens=600
    )
    return response.choices[0].message.content

# --- Streamlit UI ---
st.title("📝 Executive Summary Generator from SSC Feedback")

uploaded_file = st.file_uploader("Upload SSC Feedback Excel", type=["xlsx"])

if uploaded_file:
    df = pd.read_excel(uploaded_file)

    if "Name" not in df.columns or "Summary" not in df.columns:
        st.error("The Excel must have columns: 'Name' and 'Summary'")
    else:
        if st.button("🧠 Generate Executive Summaries"):
            output_data = []
            progress = st.progress(0)
            total = len(df)

            for i, row in df.iterrows():
                name = row["Name"]
                summary_input = row["Summary"]
                exec_summary = generate_summary(summary_input)
                output_data.append({"Name": name, "Executive Summary": exec_summary})
                progress.progress((i + 1) / total)

            output_df = pd.DataFrame(output_data)
            st.success("✅ Executive summaries generated!")
            st.dataframe(output_df)

            buffer = BytesIO()
            output_df.to_excel(buffer, index=False, engine="openpyxl")
            buffer.seek(0)

            st.download_button(
                label="📥 Download Executive Summaries",
                data=buffer,
                file_name="executive_summaries.xlsx",
                mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
            )
